#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# The setup only Tyler can do for MANTA-demo: the read token for MANTA, the
# sign-in secret, the deploy key the baseline job pushes over, the ruleset
# that makes the gate a required check, the golden PR, and the optional key
# that flips the AI scenes live. Run from the MANTA-demo checkout, signed in
# to gh as tyler-maddox-gdit (`gh auth switch -u tyler-maddox-gdit`).

TOTAL_STAGES=8
REPO="tyler-maddox-gdit/MANTA-demo"
export GH_REPO="$REPO"   # every gh call below targets the demo repo

banner "MANTA-demo setup"

stage "Check: gh is signed in as tyler-maddox-gdit"
say "Every secret below lands on $REPO, so gh must be the owner's account."
if gh auth status 2>/dev/null | grep -q "account tyler-maddox-gdit"; then
  say "gh knows tyler-maddox-gdit."
else
  warn "gh is not signed in as tyler-maddox-gdit."
  step "Run: gh auth login (or gh auth switch -u tyler-maddox-gdit) in another terminal."
fi
pause

stage "MANTA_READ_TOKEN: the fine-grained PAT CI installs MANTA with"
say "The demo repo is public and MANTA is private, so npm ci reaches MANTA over this token."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: MANTA-demo read. Resource owner: tyler-maddox-gdit."
step "Expiration: 1 year (the maximum). Note the date: DEMO.md's setup page needs it."
step "Repository access: Only select repositories → MANTA."
step "Permissions → Repository permissions → Contents: Read-only. Nothing else."
step "Generate token, then copy it (it is shown once)."
ask_secret MANTA_READ_TOKEN "Paste the token:"
ask MANTA_READ_TOKEN_EXPIRES "Its expiry date (YYYY-MM-DD):"
set_secret MANTA_READ_TOKEN "$MANTA_READ_TOKEN"
if [[ -f DEMO.md ]] && grep -q "MANTA_READ_TOKEN expires:" DEMO.md; then
  sed -i.bak "s/MANTA_READ_TOKEN expires: .*/MANTA_READ_TOKEN expires: $MANTA_READ_TOKEN_EXPIRES/" DEMO.md && rm -f DEMO.md.bak
  say "Wrote the expiry into DEMO.md (commit it)."
else
  note "Write 'MANTA_READ_TOKEN expires: $MANTA_READ_TOKEN_EXPIRES' into DEMO.md's setup page."
fi

stage "MANTA_SECRET_DEMO_PW: the sign-in password the nightly types"
say "The demo site's one password is benefits-demo; the nightly's Sign in path reads it as {{secret:demo-pw}}."
if confirm "Set MANTA_SECRET_DEMO_PW = benefits-demo on $REPO now"; then
  set_secret MANTA_SECRET_DEMO_PW "benefits-demo"
else
  SKIPPED+=("GitHub secret MANTA_SECRET_DEMO_PW (gh secret set MANTA_SECRET_DEMO_PW, value benefits-demo)")
fi

stage "MANTA_DEMO_DEPLOY_KEY: the key the baseline job pushes to main over"
say "A required check blocks every push to main, the bot's baseline commit included."
say "A deploy key with write access, listed as a ruleset bypass, is how that commit lands."
KEYFILE="$(mktemp -d)/manta-demo-deploy"
ssh-keygen -q -t ed25519 -N "" -C "MANTA-demo baseline job" -f "$KEYFILE"
say "Generated a key pair under $(dirname "$KEYFILE")."
open_url "https://github.com/$REPO/settings/keys/new"
step "Title: baseline job. Tick 'Allow write access'. Paste this public key:"
printf '\n%s\n\n' "$(cat "$KEYFILE.pub")"
pause "Press Enter once the deploy key is added"
set_secret MANTA_DEMO_DEPLOY_KEY "$(cat "$KEYFILE")"
rm -rf "$(dirname "$KEYFILE")"
say "The private half is now only in the repo secret; the local copy is gone."

stage "Ruleset on main: the gate is a required check, the deploy key bypasses it"
open_url "https://github.com/$REPO/settings/rules/new?target=branch"
step "Name: main. Target branches: Include default branch. Enforcement: Active."
step "Tick 'Require status checks to pass'; add the check named 'gate' (the gate workflow's job)."
step "Leave 'Require a pull request before merging' unticked (the demo merges from the PR page anyway)."
step "Bypass list: add 'Deploy keys' (the baseline job) and 'Repository admin' (so reset can force-push main). Save."
note "Until the gate workflow has run once, the check 'gate' may not be offered in the picker: open a PR first, then come back."
pause

stage "Actions and code scanning on the public repo"
open_url "https://github.com/$REPO/settings/actions"
step "Actions permissions: Allow all actions and reusable workflows."
step "Workflow permissions: Read repository contents (each workflow declares what it needs)."
open_url "https://github.com/$REPO/settings/security_analysis"
step "Code scanning: no setup needed for a public repo — the gate uploads a SARIF file itself. Just check the section is present."
pause

stage "The golden PR: MANTA's pre-run review, opened once and never closed"
say "A pull request from golden/upload-documents onto main. The post is written onto it later from the pr snapshot."
if confirm "Create the label 'golden' and open the golden PR on $REPO now"; then
  gh label create golden --description "The preserved PR holding MANTA's pre-run output; never close, never commit a suggestion" --color FBCA04 2>/dev/null || true
  gh pr create --base main --head golden/upload-documents --label golden \
    --title "Upload documents (golden PR — MANTA pre-run)" \
    --body "The feature branch's change, kept open as the golden PR: MANTA's review and comment here were posted once from a snapshot run (pre-run). Never merge, never commit a suggestion; see DEMO.md." \
    && say "Golden PR opened." || SKIPPED+=("golden PR (gh pr create --base main --head golden/upload-documents --label golden)")
else
  SKIPPED+=("golden PR (gh pr create --base main --head golden/upload-documents --label golden)")
fi

stage "Optional: ANTHROPIC_API_KEY flips the AI scenes live"
say "With this secret the gate runs cluster,fix --scope new and the nightly runs every skill; without it the same workflows run bare and the scenes say 'pre-run'."
if confirm "Do you have an Anthropic API key to set now"; then
  open_url "https://console.anthropic.com/settings/keys"
  ask_secret ANTHROPIC_API_KEY "Paste the key:"
  [[ -n "$ANTHROPIC_API_KEY" ]] && set_secret ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
else
  note "Skipped. Add it any time with: gh secret set ANTHROPIC_API_KEY"
fi

finish
say "Next: run 'npm run demo -- status', then the Windows checklist on MANTA issue #812."
